using System.Collections; using UnityEngine; namespace Reflectable { public sealed class CameraShake:MonoBehaviour { public float MaxIntensity=.18f; Vector3 rest; void Awake(){rest=transform.localPosition;} public void Shake(float intensity){StopAllCoroutines();StartCoroutine(Run(Mathf.Min(MaxIntensity,intensity)));} IEnumerator Run(float v){for(float t=.18f;t>0;t-=Time.deltaTime){transform.localPosition=rest+(Vector3)Random.insideUnitCircle*v*(t/.18f);yield return null;}transform.localPosition=rest;} } }
